fifo-inventory-b0-s10:
def solve(lots,demand):
    if sum(q for q,p in lots) < demand: return None
    remaining = []
    cost = 0
    for q,p in lots:
        used = min(q,demand)
        demand -= used
        cost += used*p
        if q-used: remaining.append([q-used,p])
    return [cost,remaining]

